// Collapse the (N) cookie rows to a single item so the listings query below
// runs exactly once. The cookie data itself is read in Build digest via a
// node reference ($('Fetch cookie health')), not through the item flow.
return [{ json: { ok: true } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const today = $now.toFormat('dd.MM.yyyy');
const head = '\u{1F5DE} <b>Appart Bulle — digest ' + today + '</b>\n';
let text;
if (!rows.length) {
  text = head + 'Aucune nouvelle annonce ces dernières 24 h.';
} else {
  const tierEmoji = { cheap: '\u{1F49A}', market: '\u{1F7E1}', expensive: '\u{1F534}' };
  const lines = rows.slice(0, 15).map(r => {
    const rent = r.rent_gross ?? r.rent_net;
    const spec = [r.rooms ? r.rooms + 'p' : null, r.m2 ? r.m2 + ' m²' : null, rent ? 'CHF ' + rent : null, r.commune].filter(Boolean).join(' · ');
    const score = r.fit_score ?? '?';
    return '• ★' + score + ' ' + (tierEmoji[r.price_tier] || '') + ' <a href="' + r.url + '">' + esc(spec) + '</a> <i>via ' + esc(r.source) + '</i>';
  });
  text = head + rows.length + ' nouvelle(s) annonce(s) ces dernières 24 h:\n' + lines.join('\n');
  if (rows.length > 15) text += '\n… et ' + (rows.length - 15) + ' de plus';
}
// Cookie-health footer: surfaces DataDome session state every morning so an
// expired token is visible — the circuit breaker otherwise stops SMG fetches
// silently (immoscout24 / homegate enrichment goes dark until a re-seed).
const humanAge = s => {
  s = Number(s);
  if (!isFinite(s)) return '?';
  const h = Math.floor(s / 3600);
  if (h < 1) return "à l'instant";
  if (h < 24) return 'il y a ' + h + ' h';
  return 'il y a ' + Math.floor(h / 24) + ' j';
};
const cookies = $('Fetch cookie health').all().map(i => i.json).filter(c => c && c.portal);
if (cookies.length) {
  const cl = cookies.map(c => {
    const ok = c.status === 'active';
    const mark = ok ? '\u2705' : '\u{1F534}';
    const tail = ok ? ('maj ' + humanAge(c.age_secs)) : 'EXPIRÉ — re-seed requis';
    return '• ' + esc(c.portal) + ' ' + mark + ' ' + tail;
  });
  text += '\n\n\u{1F511} <b>Cookies DataDome</b>\n' + cl.join('\n');
}
return [{ json: { text } }];
